// Contract Standing supply contract: the same item, quantity, price and terms re-ordered every period.
// Each run becomes an ordinary two-sided trade.
type Contract struct {
	Buyer     TradeParty    `json:"buyer"`
	Code      string        `json:"code"`
	CreatedAt time.Time     `json:"createdAt"`
	Every     ContractEvery `json:"every"`
	Id        string        `json:"id"`
	Item      string        `json:"item"`
	NextAt    time.Time     `json:"nextAt"`

	// Orders Trade ids, oldest first (the proposer's copy).
	Orders []struct {
		At           time.Time `json:"at"`
		BuyerTxId    *string   `json:"buyerTxId,omitempty"`
		SupplierTxId *string   `json:"supplierTxId,omitempty"`
	} `json:"orders"`

	// ProposedBy Side of a two-sided trade.
	ProposedBy Role `json:"proposedBy"`
	Quantity   struct {
		Unit  string  `json:"unit"`
		Value float64 `json:"value"`
	} `json:"quantity"`

	// Runs Orders to place in total; the contract ends after the last one.
	Runs         int            `json:"runs"`
	SourceTxId   *string        `json:"sourceTxId,omitempty"`
	Status       ContractStatus `json:"status"`
	Supplier     TradeParty     `json:"supplier"`
	Terms        PaymentTerms   `json:"terms"`
	UnitPriceIdr int            `json:"unitPriceIdr"`
}

